import{j as e}from"./blog-pages-CPaMOKsP.js";import{P as i}from"./compare-pages-DL36og6S.js";import{U as a}from"./UsecaseDeepDive-CbTz76P-.js";const n=[{factor:"Asset count (typical refinery)",atlantis:"200–800 pressure vessels",competitor:"—"},{factor:"Primary failure modes",atlantis:"Internal corrosion, external corrosion, CUI, sour service mechanisms, HTHA, fatigue, brittle fracture below MDMT",competitor:"—"},{factor:"Code references",atlantis:"API 510 (in-service), ASME Section VIII Div. 1/2 (design), API 579 (FFS), API 581 (RBI), API 571 (damage mechanisms)",competitor:"—"},{factor:"NDT methods",atlantis:"UT (B/C-scan, PAUT, AUT), RT, MT, PT, eddy current, AE, guided wave",competitor:"—"},{factor:"Inspection cycle",atlantis:"RBI-driven typically 5–10 years internal; external visual at 5 years; CML thickness as RBI requires",competitor:"—"},{factor:"Atlantis ROI typical",atlantis:"Embedded in refinery / petrochem deployment ROI",competitor:"—"},{factor:"Implementation",atlantis:"Pressure vessel workflow ships as part of process unit deployment",competitor:"—"}],s=[{question:"How does API 510 inspection planning work in Atlantis?",answer:"API 510 inspection planning runs natively in the platform. The default inspection interval comes from RBI calculation (API 581) per vessel; if RBI isn&rsquo;t implemented, the API 510 default intervals apply (5 years internal / 5 years external visual / CMLs as required). Atlantis tracks every CML reading, calculates corrosion rate from successive readings, and projects t-actual vs t-min and remaining life. The next-due inspection date updates automatically as new data arrives."},{question:"What about MDMT and brittle fracture?",answer:"Minimum Design Metal Temperature (MDMT) and brittle fracture susceptibility track on the vessel record per ASME Section VIII Div. 1 UCS-66 / UG-20(f). Atlantis flags any operating condition that approaches or violates MDMT (typically when pressure-test conditions are below normal operating temperature, or during cold-startup transients) and supports the API 579 Part 3 brittle fracture FFS for vessels operating below the original design MDMT after material property reassessment."},{question:"How does the CML grid relate to the vessel geometry?",answer:"Each CML is geo-located on the 3D vessel model — head / shell course / nozzle / weld / supports. Inspector arrives at the vessel knowing exactly which CML to read and where it sits geometrically. The 3D vessel rendering color-codes CMLs by remaining-life severity. Click-through to the CML record shows thickness history, corrosion rate, t-min, and projected next-inspection date. Multi-decade trending across vessel inspections supports defensible re-rating decisions."},{question:"What about FFS for cracks, blisters, HIC, and other indications?",answer:"API 579 Level 1, 2, and 3 FFS supported natively for general metal loss (Part 4), local metal loss (Part 5), pitting (Part 6), blisters and laminations (Part 7), HIC and SOHIC (Part 7), creep (Part 10), fire damage (Part 11), brittle fracture (Part 3), fatigue (Part 14), and crack-like flaws (Part 9). Calculation inputs come from the inspection record; outputs flow into the integrity decision (acceptable / not acceptable / requires further evaluation) and into the recommended action."},{question:"How does this fit with the company&rsquo;s pressure equipment integrity program?",answer:"Atlantis fits the vessel workflow into the broader process-unit / plant integrity program that the operator&rsquo;s integrity authority owns. The platform doesn&rsquo;t prescribe the program — it executes it. Atlantis Level III consultants (included on enterprise engagements) work with your integrity authority during deployment to align inspection plan templates, FFS workflow, and RBI scoring to the operator&rsquo;s standards."}];function d(){const r={"@context":"https://schema.org","@graph":[{"@type":"Article",headline:"Atlantis Digital Twin for Pressure Vessels: API 510 / 579 / 581 Workflow [2026]",datePublished:"2026-05-09",dateModified:"2026-05-09",author:{"@type":"Person",name:"Anoop Rayavarapu"},publisher:{"@type":"Organization",name:"Atlantis NDT"},mainEntityOfPage:{"@type":"WebPage","@id":"https://atlantisndt.com/digital-twins/pressure-vessel"}},{"@type":"FAQPage",mainEntity:s.map(t=>({"@type":"Question",name:t.question,acceptedAnswer:{"@type":"Answer",text:t.answer}}))}]};return e.jsx(i,{title:"Atlantis Digital Twin for Pressure Vessels: API 510, FFS, RBI Workflow [2026]",description:"Pressure vessel digital twin: API 510 inspection cycle, CML thickness trending, API 579 FFS Level 1/2/3, API 581 RBI scoring, MDMT brittle fracture, multi-decade vessel record.",canonical:"https://atlantisndt.com/digital-twins/pressure-vessel",eyebrow:"Asset-Class Use Case",h1:"Atlantis Digital Twin for Pressure Vessels: API 510 to FFS to RBI [2026]",intro:"Pressure vessels are the backbone of every process plant — 200–800 per refinery, with API 510 inspection cycles, API 579 FFS calculations, and API 581 RBI scoring driving the integrity workflow. Atlantis Digital Twin manages all of it natively with multi-decade vessel records.",heroGradient:"from-slate-700 to-blue-800",competitorLabel:"Pressure Vessel Specifics",compareRows:n,faqs:s,related:[{href:"/digital-twins/refinery",title:"Refinery",blurb:"Pressure vessels in the broader refinery integrity context."},{href:"/digital-twins/heat-exchanger",title:"Heat Exchanger",blurb:"Adjacent asset class — shell-side workflow shares the API 510 base."},{href:"/digital-twins/petrochemical-complex",title:"Petrochem Complex",blurb:"Pressure vessels in petrochem service environments."},{href:"/digital-twins",title:"Atlantis Digital Twin",blurb:"Product page — features, pricing, case studies."},{href:"/api-510-certification",title:"API 510 Certification",blurb:"The inspector certification underpinning the workflow."},{href:"/contact",title:"Book a Vessel Demo",blurb:"Bring one vessel&rsquo;s API 510 history. We&rsquo;ll show your vessel as a twin in 30 minutes."}],ctaTitle:"See Your Pressure Vessels as Live Integrity Twins",ctaSubtitle:"Bring one vessel’s API 510 history and CML data. We’ll have it running as an Atlantis twin in a 30-minute demo.",structuredData:r,bodyChildren:e.jsxs(e.Fragment,{children:[e.jsx("h2",{children:"The pressure vessel as the integrity-twin canonical asset"}),e.jsx("p",{children:"If a digital twin earns its keep on any single asset class, it’s the pressure vessel. Vessels are high-value (large capital cost, central to process operation), high-consequence (failure = explosion / release / personnel harm), and inspection-intensive (CMLs across the vessel, multi-decade thickness trends, API 510 / 579 / 581 workflow on every major vessel). The integrity team needs structured, queryable, defensible data — not a stack of paper inspection reports."}),e.jsx("h2",{children:"API 510 workflow native to Atlantis"}),e.jsx("p",{children:"The default inspection interval for each vessel comes from RBI calculation (API 581); if RBI isn’t fully implemented, the API 510 default intervals apply (5-year internal, 5-year external visual, CMLs as required). Atlantis tracks every CML reading, calculates corrosion rate from successive readings, and projects t-actual vs t-min and remaining life. The next-due inspection date updates automatically. Inspection plans for the next 12 months pre-populate from the vessel records — inspection planners don’t scramble for the next-due list, it’s already calculated."}),e.jsx("h2",{children:"CML grid on the 3D vessel"}),e.jsx("p",{children:"Each CML is geo-located on the 3D vessel — head / shell course / nozzle / weld / support. Inspector arrives knowing exactly which CMLs to read. The 3D rendering color-codes CMLs by remaining-life severity. Click-through to the CML record shows thickness history, corrosion rate, t-min, and projected next-inspection date. The visualization is what drives integrity team adoption — once they see their vessels rendered with color-coded CML state, the platform earns its keep."}),e.jsx("h2",{children:"FFS calculations native"}),e.jsx("p",{children:"API 579 Level 1, 2, and 3 FFS supported natively for the full damage-mechanism set:"}),e.jsxs("ul",{children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Part 4 — General metal loss."})," Most common FFS use case for refinery vessels."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Part 5 — Local metal loss."})," Pitting clusters, localized thinning patches."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Part 6 — Pitting damage."})," Statistical pitting analysis."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Part 7 — Blisters, HIC, and SOHIC."})," Sour service damage assessment."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Part 9 — Crack-like flaws."})," Surface and embedded cracks per fracture mechanics."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Part 10 — Creep damage."})," High-temperature service vessels."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Part 11 — Fire damage."})," Post-fire vessel reassessment."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Part 14 — Fatigue."})," Cyclic service vessels (coker drums, swing reactors)."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Part 3 — Brittle fracture."})," MDMT reassessment for cold-startup risk."]})]}),e.jsx("p",{children:"Calculation inputs come from the inspection record; outputs flow into the integrity decision and recommended action."}),e.jsx("h2",{children:"RBI scoring per API 581"}),e.jsx("p",{children:"API 581 RBI runs continuously as new inspection data arrives and as operating severity changes (pulled from the connected process historian). Risk band changes update the next-inspection date and inspection effectiveness assumptions. The RBI library — damage mechanisms, COF/POF factors, inspection effectiveness scoring — is configurable per operator standards while shipping with sensible defaults per API 581."}),e.jsx("h2",{children:"MDMT and brittle fracture"}),e.jsx("p",{children:"Minimum Design Metal Temperature (MDMT) and brittle fracture susceptibility track on the vessel record per ASME Section VIII Div. 1 UCS-66 / UG-20(f). Atlantis flags operating conditions that approach or violate MDMT (typically pressure-test conditions below normal operating, or cold-startup transients) and supports API 579 Part 3 brittle fracture FFS for vessels operating below original design MDMT after material property reassessment."}),e.jsx("h2",{children:"Multi-decade vessel record"}),e.jsx("p",{children:"Pressure vessels run for decades. The integrity team that’s running the vessel today is rarely the team that built it. Atlantis maintains the multi-decade record — every inspection, every FFS, every RBI assessment, every repair, every re-rate — with the same data quality standard. New integrity engineers on the team have a defensible historical baseline; old hands have their judgment captured in structured data. The vessel record outlives the people who maintain it."}),e.jsx(a,{slug:"pressure-vessel"})]})})}export{d as default};
